const results = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('h3')).map(h3 => {
    // Find the container for this provider card
    let el = h3;
    while (el && !el.classList.contains('provider-card') && el.tagName !== 'ARTICLE' && el.parentElement && el.parentElement.tagName !== 'MAIN' && !el.parentElement.classList.contains('search-results-list')) {
