    }
    const card = el || h3.parentElement;

    // Find link
    const link = card.querySelector('a') || h3.closest('a');

    return {
      name: h3.innerText.trim(),
      cardText: card.innerText.trim(),
      link: link ? link.href : null
    };
  });
