  return h3s.map(h3 => {
    // Traverse upwards until we find the card container
    let p = h3;
    while (p && p.parentElement && p.parentElement.tagName !== 'MAIN' && p.parentElement.tagName !== 'BODY') {
      p = p.parentElement;
      if (p.getAttribute('data-qa-target')?.includes('card') || p.className?.includes('card') || p.tagName === 'LI' || p.tagName === 'ARTICLE') {
        break;
      }
    }
    const container = p || h3;
    const links = Array.from(container.querySelectorAll('a')).map(a => ({ text: a.innerText.trim(), href: a.href }));
    const buttons = Array.from(container.querySelectorAll('button')).map(b => b.innerText.trim());

    return {
      title: h3.innerText.trim(),
      containerTag: container.tagName,
      containerClass: container.className,
      text: container.innerText.trim(),
      links,
      buttons
    };
  });
});

